style.css:
@-moz-document domain("trello.com"), url-prefix("https://trello.com/") {
/* Make lists align in a grid layout */
  .board-canvas {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 16px;
  }

  /* Adjust individual lists */
  .list-wrapper {
    width: auto !important;
  }

  /* Prevent dragging from resizing lists unexpectedly */
  .list {
    width: 100%;
  }
}
